function texto(
  valor: unknown,
  padrao = ''
): string {
  if (
    typeof valor === 'string'
  ) {
    return (
      valor.trim() ||
      padrao
    );
  }

  if (
    typeof valor === 'number'
  ) {
    return String(
      valor
    );
  }

  return padrao;
}

function normalizar(
  valor: string
): string {
  return valor
    .normalize('NFD')
    .replace(
      /[\u0300-\u036f]/g,
      ''
    )
    .trim()
    .toLowerCase();
}

function dataValida(
  valor: unknown
): Date | null {
  if (
    !valor
  ) {
    return null;
  }

  if (
    valor instanceof Date
  ) {
    return Number.isNaN(
      valor.getTime()
    )
      ? null
      : valor;
  }

  if (
    typeof valor === 'object' &&
    valor !== null &&
    'toDate' in valor
  ) {
    const conversor = (
      valor as {
        toDate?: () => Date;
      }
    ).toDate;

    return (
      typeof conversor ===
      'function'
    )
      ? dataValida(
          conversor.call(
            valor
          )
        )
      : null;
  }

  if (
    typeof valor === 'number'
  ) {
    return dataValida(
      new Date(
        valor
      )
    );
  }

  if (
    typeof valor !== 'string'
  ) {
    return null;
  }

  const brasileiro =
    valor.trim().match(
      /^(\d{2})[/-](\d{2})[/-](\d{4})/
    );

  const iso =
    valor.trim().match(
      /^(\d{4})-(\d{2})-(\d{2})/
    );

  if (
    brasileiro ||
    iso
  ) {
    const ano = Number(
      brasileiro
        ? brasileiro[3]
        : iso![1]
    );

    const mes = Number(
      brasileiro
        ? brasileiro[2]
        : iso![2]
    );

    const dia = Number(
      brasileiro
        ? brasileiro[1]
        : iso![3]
    );

    const data = new Date(
      ano,
      mes - 1,
      dia
    );

    return (
      data.getFullYear() === ano &&
      data.getMonth() === mes - 1 &&
      data.getDate() === dia
    )
      ? data
      : null;
  }

  return dataValida(
    new Date(
      valor
    )
  );
}

function dataRegistro(
  dados: Dados
): Date | null {
  const valores = [
    dados.data,
    dados.dataEscala,
    dados.dataCulto,
    dados.dataEvento,
    dados.dataAgendamento,
    dados.criadoEm,
    dados.createdAt,
    dados.dataCriacao,
    dados.timestamp,
    dados.enviadoEm,
    dados.publicadoEm,
    dados.atualizadoEm,
  ];

  for (const valor of valores) {
    const data =
      dataValida(
        valor
      );

    if (
      data
    ) {
      return data;
    }
  }

  return null;
}

function formatarData(
  data: Date | null
): string {
  if (
    !data
  ) {
    return 'Sem data';
  }

  const dia = String(
    data.getDate()
  ).padStart(
    2,
    '0'
  );

  const mes = String(
    data.getMonth() + 1
  ).padStart(
    2,
    '0'
  );

  const ano =
    data.getFullYear();

  return `${dia}/${mes}/${ano}`;
}

function nomeUsuario(
  dados: Dados
): string {
  return texto(
    dados.nome ||
      dados.nomeUsuario ||
      dados.displayName ||
      dados.usuario ||
      dados.autorNome ||
      dados.autor ||
      dados.responsavel ||
      dados.email,
    'Não informado'
  );
}

function nomesCampo(
  valor: unknown
): string[] {
  if (
    typeof valor === 'string'
  ) {
    return valor
      .split(
        /\s*[;,]\s*/
      )
      .map(
        item =>
          item.trim()
      )
      .filter(
        Boolean
      );
  }

  if (
    Array.isArray(
      valor
    )
  ) {
    return valor.reduce<
      string[]
    >(
      (
        lista,
        item
      ) =>
        lista.concat(
          nomesCampo(
            item
          )
        ),
      []
    );
  }

  if (
    valor &&
    typeof valor === 'object'
  ) {
    const item =
      valor as Dados;

    return nomesCampo(
      item.nome ||
        item.nomeUsuario ||
        item.displayName ||
        item.usuario ||
        item.label ||
        ''
    );
  }

  return [];
}

function nomePreenchido(
  nome: string,
  campo: string,
  titulo: string
): boolean {
  const nomeNormalizado =
    normalizar(
      nome
    );

  if (
    !nomeNormalizado
  ) {
    return false;
  }

  return ![
    '-',
    '--',
    'pendente',
    'disponivel',
    'nao informado',
    'selecione',
    'vazio',
    normalizar(
      campo
    ),
    normalizar(
      titulo
    ),
  ].includes(
    nomeNormalizado
  );
}

function extrairParticipacoes(
  escalas: Registro[]
): Participacao[] {
  const participacoes: Participacao[] =
    [];

  escalas.forEach(
    escala => {
      const unicosNaFuncao =
        new Set<string>();

      FUNCOES_ESCALA.forEach(
        funcao => {
          nomesCampo(
            escala.dados[
              funcao.campo
            ]
          ).forEach(
            nome => {
              if (
                !nomePreenchido(
                  nome,
                  funcao.campo,
                  funcao.titulo
                )
              ) {
                return;
              }

              const assinatura =
                `${normalizar(nome)}:` +
                `${funcao.grupo}:` +
                normalizar(
                  funcao.titulo
                );

              if (
                unicosNaFuncao.has(
                  assinatura
                )
              ) {
                return;
              }

              unicosNaFuncao.add(
                assinatura
              );

              participacoes.push({
                id:
                  `${escala.id}:` +
                  `${funcao.campo}:` +
                  normalizar(
                    nome
                  ),

                dados: {
                  nome,

                  funcao:
                    funcao.titulo,

                  grupo:
                    funcao.grupo,

                  escalaId:
                    escala.id,

                  data:
                    escala.dados.data,
                },

                data:
                  escala.data,

                nome,

                funcao:
                  funcao.titulo,

                grupo:
                  funcao.grupo,

                escalaId:
                  escala.id,
              });
            }
          );
        }
      );
    }
  );

  return participacoes;
}

function listaMusicas(
  dados: Dados
): Dados[] {
  const possibilidades = [
    dados.musicas,
    dados.listaMusicas,
    dados.repertorio,
    dados.itens,
    dados.songs,
  ];

  for (const valor of possibilidades) {
    if (
      Array.isArray(
        valor
      )
    ) {
      return valor.map(
        item =>
          typeof item === 'string'
            ? {
                nome: item,
              }
            : item || {}
      );
    }

    if (
      valor &&
      typeof valor === 'object'
    ) {
      return Object.values(
        valor
      ).map(
        item =>
          typeof item === 'string'
            ? {
                nome: item,
              }
            : (
                item ||
                {}
              ) as Dados
      );
    }
  }

  return [];
}

function quantidadeMusicas(
  dados: Dados
): number {
  const lista =
    listaMusicas(
      dados
    );

  if (
    lista.length
  ) {
    return lista.length;
  }

  const alternativas = [
    dados.quantidadeMusicas,
    dados.totalMusicas,
    dados.qtdMusicas,
  ];

  for (const valor of alternativas) {
    const numero =
      Number(
        valor
      );

    if (
      Number.isFinite(
        numero
      ) &&
      numero >= 0
    ) {
      return numero;
    }
  }

  return 0;
}

function extrairMusicas(
  repertorios: Registro[]
): Musica[] {
  return repertorios.reduce<
    Musica[]
  >(
    (
      resultado,
      repertorio
    ) => {
      const nomeRepertorio =
        texto(
          repertorio.dados.titulo ||
            repertorio.dados.nome ||
            repertorio.dados.nomeRepertorio,
          'Repertório'
        );

      const musicas =
        listaMusicas(
          repertorio.dados
        ).map(
          (
            musica,
            indice
          ) => {
            const nome =
              texto(
                musica.nome ||
                  musica.titulo ||
                  musica.musica ||
                  musica.name,
                'Música sem nome'
              );

            const tom =
              texto(
                musica.tom ||
                  musica.tonalidade ||
                  musica.key,
                'Não informado'
              );

            return {
              id:
                `${repertorio.id}:${indice}`,

              dados: {
                ...musica,

                nome,

                tom,

                repertorio:
                  nomeRepertorio,
              },

              data:
                dataRegistro(
                  musica
                ) ||
                repertorio.data,

              nome,

              tom,

              repertorio:
                nomeRepertorio,
            };
          }
        );

      return resultado.concat(
        musicas
      );
    },
    []
  );
}

function mesmoMes(
  data: Date | null
): boolean {
  if (
    !data
  ) {
    return false;
  }

  const agora =
    new Date();

  return (
    data.getMonth() ===
      agora.getMonth() &&
    data.getFullYear() ===
      agora.getFullYear()
  );
}

function filtrarPeriodo<
  T extends Registro
>(
  registros: T[],
  periodo: Periodo
): T[] {
  if (
    periodo === 'todos'
  ) {
    return registros;
  }

  const limite =
    new Date();

  limite.setHours(
    0,
    0,
    0,
    0
  );

  limite.setDate(
    limite.getDate() -
      Number(
        periodo
      )
  );

  return registros.filter(
    registro =>
      !!registro.data &&
      registro.data.getTime() >=
        limite.getTime()
  );
}

function intervaloPeriodoMesAtual(
  periodo: Periodo
): {
  inicio: Date;
  fim: Date;
} {
  const agora = new Date();
  const ano = agora.getFullYear();
  const mes = agora.getMonth();
  const ultimoDiaMes = new Date(
    ano,
    mes + 1,
    0
  ).getDate();

  const diaFinal =
    periodo === 'todos'
      ? ultimoDiaMes
      : agora.getDate();

  const quantidadeDias =
    periodo === 'todos'
      ? ultimoDiaMes
      : Number(periodo);

  const diaInicial =
    periodo === 'todos'
      ? 1
      : Math.max(
          1,
          diaFinal - quantidadeDias + 1
        );

  return {
    inicio: new Date(
      ano,
      mes,
      diaInicial,
      0,
      0,
      0,
      0
    ),
    fim: new Date(
      ano,
      mes,
      diaFinal,
      23,
      59,
      59,
      999
    ),
  };
}

function filtrarPeriodoMesAtual<
  T extends Registro
>(
  registros: T[],
  periodo: Periodo
): T[] {
  const {
    inicio,
    fim,
  } = intervaloPeriodoMesAtual(
    periodo
  );

  return registros.filter(
    registro =>
      !!registro.data &&
      registro.data.getTime() >=
        inicio.getTime() &&
      registro.data.getTime() <=
        fim.getTime()
  );
}

function ranking(
  registros: Registro[],
  obterNome: (
    registro: Registro
  ) => string,
  limite = 8
): ItemGrafico[] {
  const agrupados =
    new Map<
      string,
      {
        titulo: string;
        valor: number;
      }
    >();

  registros.forEach(
    registro => {
      const titulo =
        texto(
          obterNome(
            registro
          ),
          'Não informado'
        );

      const chave =
        normalizar(
          titulo
        );

      const atual =
        agrupados.get(
          chave
        );

      agrupados.set(
        chave,
        {
          titulo:
            atual?.titulo ||
            titulo,

          valor:
            (
              atual?.valor ||
              0
            ) + 1,
        }
      );
    }
  );

  return Array.from(
    agrupados.values()
  )
    .sort(
      (
        primeiro,
        segundo
      ) =>
        segundo.valor -
        primeiro.valor
    )
    .slice(
      0,
      limite
    )
    .map(
      (
        item,
        indice
      ) => ({
        ...item,

        cor:
          CORES[
            indice %
              CORES.length
          ],
      })
    );
}

function graficoMeses(
  registros: Registro[],
  cor: string
): ItemGrafico[] {
  const agora =
    new Date();

  return Array.from(
    {
      length: 6,
    },

    (
      _,
      indice
    ) => {
      const referencia =
        new Date(
          agora.getFullYear(),
          agora.getMonth() -
            (
              5 -
              indice
            ),
          1
        );

      const valor =
        registros.filter(
          registro =>
            registro.data &&
            registro.data.getMonth() ===
              referencia.getMonth() &&
            registro.data.getFullYear() ===
              referencia.getFullYear()
        ).length;

      return {
        titulo:
          MESES_CURTOS[
            referencia.getMonth()
          ],

        valor,

        cor,
      };
    }
  );
}

function graficoDiasMesAtual(
  registros: Registro[],
  periodo: Periodo,
  cor: string
): ItemGrafico[] {
  const {
    inicio,
    fim,
  } = intervaloPeriodoMesAtual(
    periodo
  );

  const dias: ItemGrafico[] = [];
  const cursor = new Date(inicio);

  while (
    cursor.getTime() <=
    fim.getTime()
  ) {
    const dia = cursor.getDate();
    const mes = cursor.getMonth();
    const ano = cursor.getFullYear();

    const valor = registros.filter(
      registro =>
        !!registro.data &&
        registro.data.getDate() === dia &&
        registro.data.getMonth() === mes &&
        registro.data.getFullYear() === ano
    ).length;

    dias.push({
      titulo: String(dia).padStart(2, '0'),
      valor,
      cor,
    });

    cursor.setDate(
      cursor.getDate() + 1
    );
  }

  return dias;
}

function montarIntegrantes(
  registros: Registros,
  participacoes: Participacao[]
): Registro[] {
  /*
   * Define quais nomes realmente pertencem à lista atual
   * da tela de Presença.
   */
  const nomesPermitidos = new Map<string, string>();

  NOMES_INTEGRANTES_PRESENCA.forEach(nome => {
    nomesPermitidos.set(normalizar(nome), nome);
  });

  const encontrados = new Map<string, Registro>();

  /*
   * Cria inicialmente um registro para cada integrante oficial.
   * Assim, pessoas da lista de presença continuam aparecendo
   * mesmo que ainda não tenham participado de alguma escala.
   */
  NOMES_INTEGRANTES_PRESENCA.forEach(nome => {
    const chave = normalizar(nome);

    encontrados.set(chave, {
      id: `presenca:${chave}`,
      data: null,
      dados: {
        nome,
      },
    });
  });

  /*
   * Complementa os dados sem permitir a entrada de pessoas
   * que não fazem parte da lista oficial.
   */
  function acrescentar(registro: Registro, nomeInformado: string) {
    const chave = normalizar(nomeInformado);

    if (!chave || !nomesPermitidos.has(chave)) {
      return;
    }

    const nomeOficial = nomesPermitidos.get(chave)!;
    const registroAtual = encontrados.get(chave);

    const dadosAnteriores = registroAtual?.dados || {};
    const dadosNovos = registro.dados || {};

    /*
     * Mantém informações já encontradas e adiciona os dados
     * complementares disponíveis no novo registro.
     */
    const dadosCombinados: Dados = {
      ...dadosNovos,
      ...dadosAnteriores,
      nome: nomeOficial,
    };

    /*
     * Garante que a foto seja preservada independentemente
     * do campo utilizado pelo cadastro do usuário.
     */
    const foto =
      dadosNovos.foto ||
      dadosNovos.fotoPerfil ||
      dadosNovos.photoURL ||
      dadosNovos.avatar ||
      dadosAnteriores.foto ||
      dadosAnteriores.fotoPerfil ||
      dadosAnteriores.photoURL ||
      dadosAnteriores.avatar;

    if (foto) {
      dadosCombinados.foto = foto;
    }

    /*
     * Preserva a função identificada nas escalas ou
     * no cadastro do integrante.
     */
    const funcao =
      dadosAnteriores.funcao ||
      dadosNovos.funcao ||
      dadosNovos.instrumento ||
      dadosNovos.cargo;

    if (funcao) {
      dadosCombinados.funcao = funcao;
    }

    /*
     * Mantém o e-mail quando disponível, sem adicionar
     * usuários que estão fora da lista de presença.
     */
    const email =
      dadosAnteriores.email ||
      dadosNovos.email;

    if (email) {
      dadosCombinados.email = email;
    }

    encontrados.set(chave, {
      id: registroAtual?.id || registro.id,
      data: registro.data || registroAtual?.data || null,
      dados: dadosCombinados,
    });
  }

  /*
   * Acrescenta informações dos documentos de usuários
   * somente quando o nome pertence à lista oficial.
   */
  registros.usuarios.forEach(registro => {
    const nome = nomeUsuario(registro.dados);

    acrescentar(registro, nome);
  });

  /*
   * Mapeia os usuários pelo UID para relacionar fotos
   * gravadas em fotosPorUid com seus respectivos nomes.
   */
  const usuariosPorUid = new Map<string, Registro>();

  registros.usuarios.forEach(registro => {
    usuariosPorUid.set(registro.id, registro);

    const uid =
      registro.dados.uid ||
      registro.dados.userId ||
      registro.dados.usuarioId;

    if (typeof uid === 'string' && uid.trim()) {
      usuariosPorUid.set(uid, registro);
    }
  });

  /*
   * Acrescenta dados e fotos que existem na coleção
   * responsável pela tela de Presença.
   */
  registros.presencas.forEach(registro => {
    const fotosUsuarios = registro.dados.fotosUsuarios;

    if (
      fotosUsuarios &&
      typeof fotosUsuarios === 'object' &&
      !Array.isArray(fotosUsuarios)
    ) {
      Object.entries(fotosUsuarios).forEach(([nome, foto]) => {
        if (typeof foto !== 'string') {
          return;
        }

        acrescentar(
          {
            id: `presenca:foto:${normalizar(nome)}`,
            data: registro.data,
            dados: {
              nome,
              foto,
            },
          },
          nome
        );
      });
    }

    const fotosPorUid = registro.dados.fotosPorUid;

    if (
      fotosPorUid &&
      typeof fotosPorUid === 'object' &&
      !Array.isArray(fotosPorUid)
    ) {
      Object.entries(fotosPorUid).forEach(([uid, foto]) => {
        if (typeof foto !== 'string') {
          return;
        }

        const usuario = usuariosPorUid.get(uid);

        if (!usuario) {
          return;
        }

        const nome = nomeUsuario(usuario.dados);

        acrescentar(
          {
            id: `presenca:uid:${uid}`,
            data: registro.data,
            dados: {
              ...usuario.dados,
              nome,
              foto,
            },
          },
          nome
        );
      });
    }

    /*
     * A tela de Presença salva os integrantes dentro
     * do objeto "presencas", com o nome como chave.
     */
    const presencas = registro.dados.presencas;

    if (
      presencas &&
      typeof presencas === 'object' &&
      !Array.isArray(presencas)
    ) {
      Object.entries(presencas).forEach(([nome, informacoes]) => {
        const dadosPresenca =
          informacoes &&
          typeof informacoes === 'object' &&
          !Array.isArray(informacoes)
            ? informacoes as Dados
            : {};

        acrescentar(
          {
            id: `presenca:registro:${normalizar(nome)}`,
            data: registro.data,
            dados: {
              ...dadosPresenca,
              nome,
            },
          },
          nome
        );
      });
    }

    /*
     * Mantém compatibilidade caso algum registro utilize
     * listas de participantes ou integrantes.
     */
    const listas = [
      registro.dados.participantes,
      registro.dados.integrantes,
      registro.dados.usuarios,
    ];

    listas.forEach(lista => {
      if (!Array.isArray(lista)) {
        return;
      }

      lista.forEach((item, indice) => {
        const dados =
          typeof item === 'string'
            ? { nome: item }
            : item || {};

        const nome = nomeUsuario(dados);

        acrescentar(
          {
            id: `presenca:${registro.id}:${indice}`,
            data: registro.data,
            dados,
          },
          nome
        );
      });
    });
  });

  /*
   * Usa as escalas somente para complementar as funções
   * dos integrantes que continuam na lista de presença.
   *
   * Pessoas antigas ou removidas não serão adicionadas.
   */
  participacoes.forEach(participacao => {
    acrescentar(
      {
        id: `escala:${normalizar(participacao.nome)}`,
        data: participacao.data,
        dados: {
          nome: participacao.nome,
          funcao: participacao.funcao,
        },
      },
      participacao.nome
    );
  });

  return Array.from(encontrados.values()).sort((a, b) =>
    nomeUsuario(a.dados).localeCompare(
      nomeUsuario(b.dados),
      'pt-BR'
    )
  );
}

function registrosCard(
  card: ChaveCard,
  registros: Registros,
  musicas: Musica[],
  participacoes: Participacao[],
  integrantes: Registro[]
): Registro[] {
  if (
    card === 'usuarios'
  ) {
    return integrantes;
  }

  if (
    card === 'escalas'
  ) {
    return registros.escalas;
  }

  if (
    card === 'escalasMes'
  ) {
    return registros.escalas.filter(
      item =>
        mesmoMes(
          item.data
        )
    );
  }

  if (
    card === 'repertorios'
  ) {
    return registros.repertorios;
  }

  if (
    card === 'musicas' ||
    card === 'cancoes'
  ) {
    return musicas;
  }

  if (
    card === 'integrantesEscalados'
  ) {
    return participacoes;
  }

  if (
    card === 'instrumentistas' ||
    card === 'vocais' ||
    card === 'backVocais' ||
    card === 'som' ||
    card === 'projecao'
  ) {
    return participacoes.filter(
      item =>
        item.grupo ===
        card
    );
  }

  if (
    card === 'avisos'
  ) {
    return registros.avisos;
  }

  if (
    card === 'agendas'
  ) {
    return registros.agendas;
  }

  if (
    card === 'mensagens'
  ) {
    return registros.mensagens;
  }

  return registros.pedidos;
}

function dadosRanking(
  card: ChaveCard,
  registros: Registro[]
): {
  titulo: string;
  itens: ItemGrafico[];
} {
  if (
    card === 'cancoes'
  ) {
    return {
      titulo:
        'Canções mais tocadas',

      itens:
        ranking(
          registros,

          item =>
            texto(
              item.dados.nome,
              'Música sem nome'
            )
        ),
    };
  }

  if (
    card === 'musicas'
  ) {
    return {
      titulo:
        'Tonalidades mais utilizadas',

      itens:
        ranking(
          registros,

          item =>
            texto(
              item.dados.tom,
              'Não informado'
            )
        ),
    };
  }

  if (
    card === 'integrantesEscalados'
  ) {
    return {
      titulo:
        'Integrantes mais escalados',

      itens:
        ranking(
          registros,

          item =>
            texto(
              item.dados.nome,
              'Não informado'
            )
        ),
    };
  }

  if (
    [
      'instrumentistas',
      'vocais',
      'backVocais',
      'som',
      'projecao',
    ].includes(
      card
    )
  ) {
    return {
      titulo:
        'Integrantes com mais participações',

      itens:
        ranking(
          registros,

          item =>
            texto(
              item.dados.nome,
              'Não informado'
            )
        ),
    };
  }

  if (
    card === 'usuarios'
  ) {
    return {
      titulo:
        'Distribuição por função',

      itens:
        ranking(
          registros,

          item =>
            texto(
              item.dados.funcao ||
                item.dados.instrumento ||
                item.dados.cargo,
              'Não informado'
            )
        ),
    };
  }

  if (
    card === 'escalas' ||
    card === 'escalasMes'
  ) {
    return {
      titulo:
        'Escalas por responsável',

      itens:
        ranking(
          registros,

          item =>
            texto(
              item.dados.responsavel,
              'Não informado'
            )
        ),
    };
  }

  if (
    card === 'repertorios'
  ) {
    const itens =
      registros
        .map(
          (
            item,
            indice
          ) => ({
            titulo:
              texto(
                item.dados.titulo ||
                  item.dados.nome,
                'Repertório'
              ),

            valor:
              quantidadeMusicas(
                item.dados
              ),

            cor:
              CORES[
                indice %
                  CORES.length
              ],
          })
        )
        .sort(
          (
            primeiro,
            segundo
          ) =>
            segundo.valor -
            primeiro.valor
        )
        .slice(
          0,
          8
        );

    return {
      titulo:
        'Repertórios com mais músicas',

      itens,
    };
  }

  return {
    titulo:
      card === 'mensagens' ||
      card === 'pedidos'
        ? 'Participantes mais ativos'
        : 'Registros por responsável',

    itens:
      ranking(
        registros,

        item =>
          nomeUsuario(
            item.dados
          )
      ),
  };
}

function tituloItem(
  card: ChaveCard,
  registro: Registro
): string {
  const dados =
    registro.dados;

  if (
    card === 'usuarios' ||
    card === 'integrantesEscalados' ||
    [
      'instrumentistas',
      'vocais',
      'backVocais',
      'som',
      'projecao',
    ].includes(
      card
    )
  ) {
    return nomeUsuario(
      dados
    );
  }

  if (
    card === 'musicas' ||
    card === 'cancoes'
  ) {
    return texto(
      dados.nome ||
        dados.titulo ||
        dados.musica,
      'Música'
    );
  }

  if (
    card === 'mensagens' ||
    card === 'pedidos'
  ) {
    return nomeUsuario(
      dados
    );
  }

  if (
    card === 'escalas' ||
    card === 'escalasMes'
  ) {
    return texto(
      dados.titulo ||
        dados.nome ||
        dados.culto,
      'Escala de louvor'
    );
  }

  return texto(
    dados.titulo ||
      dados.nome ||
      dados.evento ||
      dados.assunto,
    'Registro'
  );
}

function descricaoItem(
  card: ChaveCard,
  registro: Registro
): string {
  const dados =
    registro.dados;

  if (
    card === 'usuarios'
  ) {
    return texto(
      dados.funcao ||
        dados.instrumento ||
        dados.email,
      'Integrante identificado'
    );
  }

  if (
    card === 'integrantesEscalados' ||
    [
      'instrumentistas',
      'vocais',
      'backVocais',
      'som',
      'projecao',
    ].includes(
      card
    )
  ) {
    return texto(
      dados.funcao,
      'Participação na escala'
    );
  }

  if (
    card === 'musicas' ||
    card === 'cancoes'
  ) {
    const repertorio =
      texto(
        dados.repertorio,
        'Repertório'
      );

    const tom =
      texto(
        dados.tom,
        'Não informado'
      );

    return `${repertorio} · Tom: ${tom}`;
  }

  if (
    card === 'repertorios'
  ) {
    const quantidade =
      quantidadeMusicas(
        dados
      );

    const responsavel =
      texto(
        dados.responsavel,
        'Responsável não informado'
      );

    return (
      `${quantidade} música(s) · ` +
      responsavel
    );
  }

  if (
    card === 'escalas' ||
    card === 'escalasMes'
  ) {
    return texto(
      dados.responsavel,
      'Responsável não informado'
    );
  }

  return texto(
    dados.mensagem ||
      dados.texto ||
      dados.descricao ||
      dados.pedido ||
      dados.conteudo,
    'Registro cadastrado'
  );
}

