function Rosca({
  dados,
}: {
  dados: ItemGrafico[];
}) {
  const tamanho =
    158;

  const espessura =
    16;

  const raio =
    (
      tamanho -
      espessura
    ) / 2;

  const circunferencia =
    2 *
    Math.PI *
    raio;

  const total =
    dados.reduce(
      (
        soma,
        item
      ) =>
        soma +
        item.valor,

      0
    );

  let deslocamento =
    0;

  if (
    !total
  ) {
    return (
      <EstadoVazio
        icone={
          'chart-donut'
        }
        mensagem={
          'Ainda não existem dados suficientes para esta distribuição.'
        }
      />
    );
  }

  return (
    <View
      style={
        estilos.areaRosca
      }
    >
      <View
        style={
          estilos.rosca
        }
      >
        <Svg
          width={
            tamanho
          }
          height={
            tamanho
          }
        >
          <Circle
            cx={
              tamanho / 2
            }
            cy={
              tamanho / 2
            }
            r={
              raio
            }
            stroke={
              '#24324B'
            }
            strokeWidth={
              espessura
            }
            fill={
              'transparent'
            }
          />

          {dados.map(
            (
              item,
              indice
            ) => {
              const comprimento =
                (
                  item.valor /
                  total
                ) *
                circunferencia;

              const atual =
                deslocamento;

              deslocamento +=
                comprimento;

              return (
                <Circle
                  key={
                    `${item.titulo}-${indice}`
                  }
                  cx={
                    tamanho / 2
                  }
                  cy={
                    tamanho / 2
                  }
                  r={
                    raio
                  }
                  stroke={
                    item.cor
                  }
                  strokeWidth={
                    espessura
                  }
                  fill={
                    'transparent'
                  }
                  strokeDasharray={
                    `${comprimento} ${circunferencia}`
                  }
                  strokeDashoffset={
                    -atual
                  }
                  rotation={
                    '-90'
                  }
                  origin={
                    `${tamanho / 2}, ${tamanho / 2}`
                  }
                />
              );
            }
          )}
        </Svg>

        <View
          style={
            estilos.centroRosca
          }
        >
          <Text
            style={
              estilos.valorRosca
            }
          >
            {total}
          </Text>

          <Text
            style={
              estilos.textoRosca
            }
          >
            registros
          </Text>
        </View>
      </View>

      <View
        style={
          estilos.legendasRosca
        }
      >
        {dados
          .slice(
            0,
            6
          )
          .map(
            (
              item,
              indice
            ) => (
              <View
                key={
                  `${item.titulo}-${indice}`
                }
                style={
                  estilos.linhaLegenda
                }
              >
                <View
                  style={[
                    estilos.pontoLegenda,

                    {
                      backgroundColor:
                        item.cor,
                    },
                  ]}
                />

                <Text
                  style={
                    estilos.nomeLegenda
                  }
                  numberOfLines={
                    1
                  }
                >
                  {item.titulo}
                </Text>

                <Text
                  style={
                    estilos.valorLegenda
                  }
                >
                  {item.valor}
                </Text>
              </View>
            )
          )}
      </View>
    </View>
  );
}

