function formatarDataInput(text: string) {
  let cleaned = text.replace(/\D/g, '');
  let formatted = '';
  if (cleaned.length > 4) {
    formatted = cleaned.replace(/^(\d{2})(\d{2})(\d{0,4}).*/, '$1/$2/$3');
  } else if (cleaned.length > 2) {
    formatted = cleaned.replace(/^(\d{2})(\d{0,2})/, '$1/$2');
  } else {
    formatted = cleaned;
  }
  return formatted;
}

function dataCompletaValida(valor: string) {
  const correspondencia = valor.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
  if (!correspondencia) return false;

  const dia = Number(correspondencia[1]);
  const mes = Number(correspondencia[2]);
  const ano = Number(correspondencia[3]);
  const data = new Date(ano, mes - 1, dia);

  return ano >= 1900 &&
    data.getFullYear() === ano &&
    data.getMonth() === mes - 1 &&
    data.getDate() === dia;
}

// retorna apenas dia e mês no formato dd/mm (esconde o ano)
function exibirDiaMes(data: string) {
  if (!data) return '';
  // aceita 'dd-mm-aaaa' ou 'dd/mm/aaaa' ou 'dd-mm' etc.
  const parts = data.split(/[-\/]/);
  if (parts.length >= 2) {
    const dia = parts[0].padStart(2, '0');
    const mes = parts[1].padStart(2, '0');
    return `${dia}/${mes}`;
  }
  return data;
}

function formatarDataHoraMensagem(valor?: Timestamp | Date | string | number) {
  if (!valor) return '';

  let data: Date;
  if (valor instanceof Timestamp) {
    data = valor.toDate();
  } else if (valor instanceof Date) {
    data = valor;
  } else if (typeof valor === 'number') {
    data = new Date(valor);
  } else {
    data = new Date(valor);
  }

  if (Number.isNaN(data.getTime())) return '';

  return data.toLocaleString('pt-BR', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  });
}

