function obterMensagemCarregamento(
  percentual: number
) {
  if (percentual < 25) {
    return 'Preparando o ambiente';
  }

  if (percentual < 50) {
    return 'Organizando o ministério';
  }

  if (percentual < 75) {
    return 'Carregando seus conteúdos';
  }

  if (percentual < 100) {
    return 'Quase tudo pronto';
  }

  return 'Bem-vindo ao WorshipApp';
}

export default function SplashLogoScreen({
  navigation,
}: any) {
  const {
    width,
    height,
  } = useWindowDimensions();

  const telaCompacta =
    width < 370 ||
    height < 690;

  const [
    percentual,
    setPercentual,
  ] = useState(0);

  const entrada = useRef(
    new Animated.Value(0)
  ).current;

  const escalaLogo = useRef(
    new Animated.Value(0.78)
  ).current;

  const progresso = useRef(
    new Animated.Value(0)
  ).current;

  const pulsacao = useRef(
    new Animated.Value(0)
  ).current;

  const flutuacao = useRef(
    new Animated.Value(0)
  ).current;

  const rotacao = useRef(
    new Animated.Value(0)
  ).current;

  const brilhoBarra = useRef(
    new Animated.Value(0)
  ).current;

  const navegacaoRealizada = useRef(
    false
  );

  useEffect(() => {
    let componenteAtivo = true;

    let temporizadorNavegacao:
      ReturnType<typeof setTimeout> |
      undefined;

    const entradaAnimada =
      Animated.parallel([
        Animated.timing(
          entrada,
          {
            toValue: 1,
            duration: 850,
            easing: Easing.out(
              Easing.cubic
            ),
            useNativeDriver: true,
          }
        ),

        Animated.spring(
          escalaLogo,
          {
            toValue: 1,
            friction: 7,
            tension: 42,
            useNativeDriver: true,
          }
        ),
      ]);

    const pulsacaoAnimada =
      Animated.loop(
        Animated.sequence([
          Animated.timing(
            pulsacao,
            {
              toValue: 1,
              duration: 1500,
              easing: Easing.inOut(
                Easing.ease
              ),
              useNativeDriver: true,
            }
          ),

          Animated.timing(
            pulsacao,
            {
              toValue: 0,
              duration: 1500,
              easing: Easing.inOut(
                Easing.ease
              ),
              useNativeDriver: true,
            }
          ),
        ])
      );

    const flutuacaoAnimada =
      Animated.loop(
        Animated.sequence([
          Animated.timing(
            flutuacao,
            {
              toValue: 1,
              duration: 1800,
              easing: Easing.inOut(
                Easing.ease
              ),
              useNativeDriver: true,
            }
          ),

          Animated.timing(
            flutuacao,
            {
              toValue: 0,
              duration: 1800,
              easing: Easing.inOut(
                Easing.ease
              ),
              useNativeDriver: true,
            }
          ),
        ])
      );

    const rotacaoAnimada =
      Animated.loop(
        Animated.timing(
          rotacao,
          {
            toValue: 1,
            duration: 10500,
            easing: Easing.linear,
            useNativeDriver: true,
          }
        )
      );

    const brilhoAnimado =
      Animated.loop(
        Animated.sequence([
          Animated.timing(
            brilhoBarra,
            {
              toValue: 1,
              duration: 1600,
              easing: Easing.inOut(
                Easing.ease
              ),
              useNativeDriver: true,
            }
          ),

          Animated.timing(
            brilhoBarra,
            {
              toValue: 0,
              duration: 10,
              useNativeDriver: true,
            }
          ),
        ])
      );

    entradaAnimada.start();
    pulsacaoAnimada.start();
    flutuacaoAnimada.start();
    rotacaoAnimada.start();
    brilhoAnimado.start();

    const identificadorProgresso =
      progresso.addListener(
        ({
          value,
        }) => {
          if (!componenteAtivo) {
            return;
          }

          const valorAtual =
            Math.min(
              100,
              Math.max(
                0,
                Math.round(
                  value * 100
                )
              )
            );

          setPercentual(
            valorAtual
          );
        }
      );

    Animated.timing(
      progresso,
      {
        toValue: 1,
        duration: DURACAO_CARREGAMENTO,
        easing: Easing.inOut(
          Easing.cubic
        ),
        useNativeDriver: false,
      }
    ).start();

    const cancelarAutenticacao =
      onAuthStateChanged(
        auth,
        usuario => {
          if (
            !componenteAtivo ||
            navegacaoRealizada.current
          ) {
            return;
          }

          if (
            temporizadorNavegacao
          ) {
            clearTimeout(
              temporizadorNavegacao
            );
          }

          temporizadorNavegacao =
            setTimeout(
              () => {
                if (
                  !componenteAtivo ||
                  navegacaoRealizada.current
                ) {
                  return;
                }

                navegacaoRealizada.current =
                  true;

                if (
                  usuario &&
                  usuario.emailVerified
                ) {
                  navigation.replace(
                    'Inicio'
                  );

                  return;
                }

                navigation.replace(
                  'Login'
                );
              },

              DURACAO_SPLASH
            );
        }
      );

    return () => {
      componenteAtivo = false;

      if (
        temporizadorNavegacao
      ) {
        clearTimeout(
          temporizadorNavegacao
        );
      }

      entradaAnimada.stop();
      pulsacaoAnimada.stop();
      flutuacaoAnimada.stop();
      rotacaoAnimada.stop();
      brilhoAnimado.stop();

      progresso.removeListener(
        identificadorProgresso
      );

      cancelarAutenticacao();
    };
  }, [
    brilhoBarra,
    entrada,
    escalaLogo,
    flutuacao,
    navigation,
    progresso,
    pulsacao,
    rotacao,
  ]);

  const larguraProgresso =
    progresso.interpolate({
      inputRange: [
        0,
        1,
      ],

      outputRange: [
        '0%',
        '100%',
      ],
    });

  const logoFlutuante =
    flutuacao.interpolate({
      inputRange: [
        0,
        1,
      ],

      outputRange: [
        0,
        -9,
      ],
    });

  const notasFlutuantes =
    flutuacao.interpolate({
      inputRange: [
        0,
        1,
      ],

      outputRange: [
        0,
        -14,
      ],
    });

  const escalaBrilho =
    pulsacao.interpolate({
      inputRange: [
        0,
        1,
      ],

      outputRange: [
        0.92,
        1.12,
      ],
    });

  const opacidadeBrilho =
    pulsacao.interpolate({
      inputRange: [
        0,
        1,
      ],

      outputRange: [
        0.32,
        0.75,
      ],
    });

  const opacidadeParticulas =
    pulsacao.interpolate({
      inputRange: [
        0,
        1,
      ],

      outputRange: [
        0.45,
        1,
      ],
    });

  const giroAnel =
    rotacao.interpolate({
      inputRange: [
        0,
        1,
      ],

      outputRange: [
        '0deg',
        '360deg',
      ],
    });

  const giroAnelContrario =
    rotacao.interpolate({
      inputRange: [
        0,
        1,
      ],

      outputRange: [
        '360deg',
        '0deg',
      ],
    });

  const movimentoBrilho =
    brilhoBarra.interpolate({
      inputRange: [
        0,
        1,
      ],

      outputRange: [
        -90,
        350,
      ],
    });

  const entradaConteudo =
    entrada.interpolate({
      inputRange: [
        0,
        1,
      ],

      outputRange: [
        20,
        0,
      ],
    });

  return (
    <LinearGradient
      colors={[
        '#06101D',
        '#0C1730',
        '#121933',
        '#081322',
      ]}
      locations={[
        0,
        0.35,
        0.72,
        1,
      ]}
      start={{
        x: 0,
        y: 0,
      }}
      end={{
        x: 1,
        y: 1,
      }}
      style={
        styles.container
      }
    >
      <View
        pointerEvents="none"
        style={
          styles.luzSuperior
        }
      />

      <View
        pointerEvents="none"
        style={
          styles.luzInferior
        }
      />

      <View
        pointerEvents="none"
        style={
          styles.faixaDiagonalSuperior
        }
      />

      <View
        pointerEvents="none"
        style={
          styles.faixaDiagonalInferior
        }
      />

      {PARTICULAS.map(
        (
          particula,
          indice
        ) => (
          <Animated.View
            key={
              `particula-${indice}`
            }
            pointerEvents="none"
            style={[
              styles.particula,

              {
                top:
                  particula.top,

                left:
                  particula.left,

                width:
                  particula.size,

                height:
                  particula.size,

                borderRadius:
                  particula.size / 2,

                backgroundColor:
                  particula.color,

                opacity:
                  Animated.multiply(
                    opacidadeParticulas,
                    particula.opacity
                  ),

                transform: [
                  {
                    translateY:
                      indice % 2 === 0
                        ? notasFlutuantes
                        : logoFlutuante,
                  },
                ],
              },
            ]}
          />
        )
      )}

      <Animated.View
        style={[
          styles.conteudo,

          telaCompacta &&
            styles.conteudoCompacto,

          {
            opacity:
              entrada,

            transform: [
              {
                translateY:
                  entradaConteudo,
              },
            ],
          },
        ]}
      >
        <View
          style={
            styles.seloSuperior
          }
        >
          <View
            style={
              styles.pontoSelo
            }
          />

          <Text
            style={
              styles.textoSelo
            }
          >
            MINISTÉRIO DE LOUVOR
          </Text>
        </View>

        <View
          style={[
            styles.areaLogo,

            telaCompacta &&
              styles.areaLogoCompacta,
          ]}
        >
          <Animated.View
            pointerEvents="none"
            style={[
              styles.brilhoLogo,

              telaCompacta &&
                styles.brilhoLogoCompacto,

              {
                opacity:
                  opacidadeBrilho,

                transform: [
                  {
                    scale:
                      escalaBrilho,
                  },
                ],
              },
            ]}
          />

          <Animated.View
            pointerEvents="none"
            style={[
              styles.anelExterno,

              telaCompacta &&
                styles.anelExternoCompacto,

              {
                transform: [
                  {
                    rotate:
                      giroAnel,
                  },
                ],
              },
            ]}
          >
            <View
              style={
                styles.pontoOrbitalSuperior
              }
            />

            <View
              style={
                styles.pontoOrbitalInferior
              }
            />
          </Animated.View>

          <Animated.View
            pointerEvents="none"
            style={[
              styles.anelInterno,

              telaCompacta &&
                styles.anelInternoCompacto,

              {
                transform: [
                  {
                    rotate:
                      giroAnelContrario,
                  },
                ],
              },
            ]}
          >
            <View
              style={
                styles.pontoOrbitalLateral
              }
            />
          </Animated.View>

          <Animated.View
            pointerEvents="none"
            style={[
              styles.notaSuperior,

              {
                transform: [
                  {
                    translateY:
                      notasFlutuantes,
                  },
                ],
              },
            ]}
          >
            <MaterialCommunityIcons
              name="music-note"
              size={
                telaCompacta
                  ? 19
                  : 23
              }
              color="#67E8F9"
            />
          </Animated.View>

          <Animated.View
            pointerEvents="none"
            style={[
              styles.notaLateral,

              {
                transform: [
                  {
                    translateY:
                      logoFlutuante,
                  },
                ],
              },
            ]}
          >
            <MaterialCommunityIcons
              name="music-note-eighth"
              size={
                telaCompacta
                  ? 18
                  : 21
              }
              color="#FFC857"
            />
          </Animated.View>

          <Animated.View
            style={[
              styles.logoCard,

              telaCompacta &&
                styles.logoCardCompacto,

              {
                transform: [
                  {
                    scale:
                      escalaLogo,
                  },

                  {
                    translateY:
                      logoFlutuante,
                  },
                ],
              },
            ]}
          >
            <LinearGradient
              colors={[
                'rgba(103,232,249,0.17)',
                'rgba(167,139,250,0.08)',
                'rgba(255,255,255,0.035)',
              ]}
              start={{
                x: 0,
                y: 0,
              }}
              end={{
                x: 1,
                y: 1,
              }}
              style={
                styles.logoGradiente
              }
            >
              <View
                style={
                  styles.logoBrilhoSuperior
                }
              />

              <Image
                source={
                  require(
                    '../assets/logo.Webp'
                  )
                }
                style={[
                  styles.logo,

                  telaCompacta &&
                    styles.logoCompacta,
                ]}
                resizeMode="contain"
              />
            </LinearGradient>
          </Animated.View>
        </View>

        <Text
          style={[
            styles.nomeAplicativo,

            telaCompacta &&
              styles.nomeAplicativoCompacto,
          ]}
        >
          Louvor
          {' '}
          <Text
            style={
              styles.nomeDestaque
            }
          >
            Soma
          </Text>
        </Text>

        <Text
          style={
            styles.descricao
          }
        >
          Conectando pessoas através do louvor
        </Text>

        <View
          style={
            styles.separador
          }
        >
          <View
            style={
              styles.linhaSeparador
            }
          />

          <MaterialCommunityIcons
            name="music-clef-treble"
            size={18}
            color="#5CE1E6"
          />

          <View
            style={
              styles.linhaSeparador
            }
          />
        </View>

        <View
          style={[
            styles.cardProgresso,

            telaCompacta &&
              styles.cardProgressoCompacto,
          ]}
        >
          <View
            style={
              styles.cabecalhoProgresso
            }
          >
            <View
              style={
                styles.areaStatus
              }
            >
              <View
                style={
                  styles.iconeStatus
                }
              >
                <MaterialCommunityIcons
                  name={
                    percentual >= 100
                      ? 'check-circle-outline'
                      : 'lightning-bolt-outline'
                  }
                  size={17}
                  color={
                    percentual >= 100
                      ? '#4ADE80'
                      : '#67E8F9'
                  }
                />
              </View>

              <Text
                style={
                  styles.textoStatus
                }
                numberOfLines={1}
              >
                {obterMensagemCarregamento(
                  percentual
                )}
              </Text>
            </View>

            <Text
              style={
                styles.percentual
              }
            >
              {percentual}
              %
            </Text>
          </View>

          <View
            style={
              styles.trilhoProgresso
            }
          >
            <Animated.View
              style={[
                styles.progressoPreenchido,

                {
                  width:
                    larguraProgresso,
                },
              ]}
            >
              <LinearGradient
                colors={[
                  '#4ADE80',
                  '#45E1C5',
                  '#67E8F9',
                  '#8B7BFF',
                ]}
                start={{
                  x: 0,
                  y: 0,
                }}
                end={{
                  x: 1,
                  y: 0,
                }}
                style={
                  styles.gradienteProgresso
                }
              />

              <Animated.View
                style={[
                  styles.brilhoProgresso,

                  {
                    transform: [
                      {
                        translateX:
                          movimentoBrilho,
                      },
                    ],
                  },
                ]}
              />
            </Animated.View>
          </View>

          <View
            style={
              styles.rodapeProgresso
            }
          >
            <Text
              style={
                styles.textoRodape
              }
            >
              SUA EXPERIÊNCIA COMEÇA AQUI
            </Text>

            <View
              style={
                styles.indicadores
              }
            >
              <View
                style={[
                  styles.indicador,

                  percentual >= 30 &&
                    styles.indicadorAtivo,
                ]}
              />

              <View
                style={[
                  styles.indicador,

                  percentual >= 60 &&
                    styles.indicadorAtivo,
                ]}
              />

              <View
                style={[
                  styles.indicador,

                  percentual >= 95 &&
                    styles.indicadorAtivo,
                ]}
              />
            </View>
          </View>
        </View>
      </Animated.View>

      <View
        style={
          styles.rodapeTela
        }
      >
        <MaterialCommunityIcons
          name="heart-outline"
          size={13}
          color="#65DCC2"
        />

        <Text
          style={
            styles.textoRodapeTela
          }
        >
          Feito para servir e adorar
        </Text>
      </View>
    </LinearGradient>
  );
}

